input.command:
/usr/bin/rg -n "pskb_may_pull" net/ -g '*.c' -l | while read f; do
  awk -v file="$f" '
    /pskb_may_pull/ {
      # capture this line plus next 2 lines
      line=$0; getline n1; getline n2
      if (line !~ /if/ && line !~ /return/ && line !~ /!pskb_may_pull/) {
        print file": "$0
      }
    }' "$f"
done 2>/dev/null | head -40

